// ===== Назначаем пины =====
const int BTN_PIN = 2;    // Пин для кнопки
const int LED_PIN = 8;    // Пин для светодиода
const int BUZ_PIN = 9;    // Пин для спикера

// Переменные
bool alarmActive = false;     // Флаг: включена ли тревога (false = выкл, true = вкл)
bool lastButtonState = HIGH;  // Предыдущее состояние кнопки
unsigned long lastDebounceTime = 0;
const unsigned long debounceDelay = 50; // Защита от дребезга кнопки (миллисекунды)

void setup() {
  Serial.begin(115200);

  // Настраиваем пины на вход и выход
  pinMode(BTN_PIN, INPUT_PULLUP); // Включаем внутреннюю подтяжку. Кнопка замыкает на GND
  pinMode(LED_PIN, OUTPUT);
  pinMode(BUZ_PIN, OUTPUT);

  // Выключаем всё при старте
  digitalWrite(LED_PIN, LOW);
  digitalWrite(BUZ_PIN, LOW);

  Serial.println("Система готова.");
}

void loop() {
  // Считываем состояние кнопки (LOW = нажата, HIGH = отпущена)
  bool reading = digitalRead(BTN_PIN);

  // Логика борьбы с дребезгом контактов
  if (reading != lastButtonState) {
    lastDebounceTime = millis();
  }

  if ((millis() - lastDebounceTime) > debounceDelay) {
    // Если кнопка нажата (сигнал LOW)
    if (reading == LOW) { 
      alarmActive = !alarmActive; // Переключаем режим (вкл/выкл)

      if (alarmActive) {
        Serial.println("ТРЕВОГА ВКЛЮЧЕНА!");
      } else {
        Serial.println("Тревога выключена.");
      }

      // Ждем, пока кнопку отпустят, чтобы избежать двойного срабатывания
      while(digitalRead(BTN_PIN) == LOW) { delay(10); }
    }
  }

  // Запоминаем текущее состояние
  lastButtonState = reading;

  // Управление светодиодом и спикером
  if (alarmActive) {
    digitalWrite(LED_PIN, HIGH); // Включаем светодиод
    digitalWrite(BUZ_PIN, HIGH); // Включаем звук (для активного зуммера)

    // ВАЖНО: Если у вас пассивный зуммер (просто динамик), 
    // замените строку выше на: tone(BUZ_PIN, 1000); // писк 1000 Гц
  } else {
    digitalWrite(LED_PIN, LOW);  // Выключаем светодиод
    digitalWrite(BUZ_PIN, LOW);  // Выключаем звук

    // Если использовали tone(), напишите здесь: noTone(BUZ_PIN);
  }
}
